import{_ as e,o as t,c as r,ah as s}from"./chunks/framework.Yx0DUrwu.js";const h=JSON.parse('{"title":"Seurat 教程","description":"","frontmatter":{},"headers":[],"relativePath":"tools/seurat/index.md","filePath":"tools/seurat/index.md","lastUpdated":1778485541000}'),o={name:"tools/seurat/index.md"};function n(l,a,i,u,c,d){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="seurat-教程" tabindex="-1">Seurat 教程 <a class="header-anchor" href="#seurat-教程" aria-label="Permalink to &quot;Seurat 教程&quot;">​</a></h1><p>Seurat 是 R 生态中最常用的单细胞分析框架之一。官方 vignettes 以 PBMC 数据为入口，展示从读取 10x 数据、创建 Seurat object、QC、归一化、特征选择、PCA、邻居图、聚类、UMAP 到 marker gene 的标准流程。</p><p>如果 Scanpy 是 Python/scverse 主线，Seurat 就是 R 生态主线。许多公开数据、论文补充代码和湿实验团队仍大量使用 Seurat。因此学习 Seurat 的价值不仅在于会跑 R 代码，也在于能读懂他人的分析对象和中间结果。</p><div class="path-grid"><a href="/tools/seurat/pbmc-workflow"><strong>PBMC 标准流程</strong><span>参考官方 PBMC tutorial，整理 CreateSeuratObject, QC, NormalizeData, PCA, UMAP, clusters, and markers。</span></a><a href="/tools/scanpy/"><strong>与 Scanpy 对照</strong><span>把 Seurat object 和 AnnData 对照起来，理解 metadata, reductions, assays, and layers。</span></a><a href="/tools/common-tools/"><strong>后续工具</strong><span>细胞注释、空间组学、CNV 推断和通路活性分析可以接在 Seurat 或 Scanpy 后面。</span></a><a href="/references/"><strong>参考资料</strong><span>查看 Seurat 官方教程和单细胞最佳实践资料。</span></a></div><h2 id="实践判断" tabindex="-1">实践判断 <a class="header-anchor" href="#实践判断" aria-label="Permalink to &quot;实践判断&quot;">​</a></h2><div class="doc-callout important"><strong>Seurat 的对象版本很重要</strong><p>Seurat v5 引入 layer 概念后，旧教程和旧对象的字段习惯可能不同。复现论文代码时，先记录 Seurat 版本、Assay 类型和数据所在 layer。</p></div><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li><a href="https://satijalab.org/seurat/" target="_blank" rel="noreferrer">Seurat official website</a></li><li><a href="https://satijalab.org/seurat/articles/pbmc3k_tutorial" target="_blank" rel="noreferrer">Seurat PBMC 3K guided tutorial</a></li><li><a href="https://satijalab.org/seurat/articles/essential_commands" target="_blank" rel="noreferrer">Seurat essential commands</a></li></ul>',8)])])}const S=e(o,[["render",n]]);export{h as __pageData,S as default};
